-- Every row in another table that references the upload (the same scan as tbu_upload_evidence, without its processing
-- check): the first referencing relation, or NULL. fiscal_periods.active_upload_id is a pointer, not evidence.
CREATE OR REPLACE FUNCTION public.tbu_upload_dependent_evidence(p_upload_id uuid)
RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  r record;
  v_found boolean;
BEGIN
  FOR r IN
    SELECT n.nspname AS sch, cl.relname AS tbl, a.attname AS col
      FROM pg_catalog.pg_constraint c
      JOIN pg_catalog.pg_class cl ON cl.oid = c.conrelid
      JOIN pg_catalog.pg_namespace n ON n.oid = cl.relnamespace
      JOIN pg_catalog.pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = c.conkey[1]
     WHERE c.contype = 'f'
       AND c.confrelid = 'public.trial_balance_uploads'::regclass
       AND c.conrelid <> 'public.trial_balance_uploads'::regclass
       AND NOT (c.conrelid = 'public.fiscal_periods'::regclass AND a.attname = 'active_upload_id')
     ORDER BY 1, 2, 3
  LOOP
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I.%I WHERE %I = $1)', r.sch, r.tbl, r.col) INTO v_found USING p_upload_id;
    IF v_found THEN RETURN r.sch || '.' || r.tbl; END IF;
  END LOOP;
  RETURN NULL;
END;
$$;

-- NULL = this upload is a genuinely refused replacement whose exact predecessor may be restored; otherwise the reason.
CREATE OR REPLACE FUNCTION public.tbu_refused_replacement_block(p_upload_id uuid)
RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_rep  public.trial_balance_uploads%ROWTYPE;
  v_prev public.trial_balance_uploads%ROWTYPE;
  v_run  public.engine_runs%ROWTYPE;
BEGIN
  SELECT * INTO v_rep FROM public.trial_balance_uploads t WHERE t.id = p_upload_id;
  IF v_rep.id IS NULL OR v_rep.replaces_upload_id IS NULL THEN RETURN 'not_a_replacement'; END IF;
  -- The exact current replacement: the period's active upload (one per period), never one a newer upload replaced.
  IF v_rep.lifecycle_state NOT IN ('active_unprocessed', 'active_processing', 'active_processed', 'blocked') THEN RETURN 'not_current'; END IF;
  -- A terminal ingestion refusal, not merely a blocked result.
  IF v_rep.current_engine_run_id IS NULL THEN RETURN 'not_refused'; END IF;
  SELECT * INTO v_run FROM public.engine_runs er WHERE er.id = v_rep.current_engine_run_id;
  IF v_run.status = 'running' THEN RETURN 'processing_in_progress'; END IF;
  IF v_rep.status IS DISTINCT FROM 'blocked' OR v_run.id IS NULL OR v_run.status IS DISTINCT FROM 'failed'
     OR v_run.error_code IS DISTINCT FROM 'INGESTION_REFUSED' THEN
    RETURN 'not_refused';
  END IF;
  IF jsonb_typeof(v_rep.processing_result #> '{summary,total_accounts}') IS DISTINCT FROM 'number'
     OR (v_rep.processing_result #>> '{summary,total_accounts}')::numeric <> 0
     OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(
                      CASE WHEN jsonb_typeof(v_rep.processing_result #> '{ingestion,issues}') = 'array'
                           THEN v_rep.processing_result #> '{ingestion,issues}' ELSE '[]'::jsonb END) i
                     WHERE i->>'severity' = 'blocking') THEN
    RETURN 'not_refused';
  END IF;
  IF EXISTS (SELECT 1 FROM public.tb_certifications c WHERE c.upload_id = v_rep.id) THEN RETURN 'certified'; END IF;
  IF public.tbu_upload_dependent_evidence(v_rep.id) IS NOT NULL THEN RETURN 'dependent_evidence'; END IF;
  -- Its exact superseded predecessor, in the same entity and period.
  SELECT * INTO v_prev FROM public.trial_balance_uploads t WHERE t.id = v_rep.replaces_upload_id;
  IF v_prev.id IS NULL OR v_prev.lifecycle_state <> 'superseded' OR v_prev.superseded_by_upload_id IS DISTINCT FROM v_rep.id
     OR v_prev.company_id IS DISTINCT FROM v_rep.company_id OR v_prev.period_year IS DISTINCT FROM v_rep.period_year
     OR v_prev.period_id IS DISTINCT FROM v_rep.period_id THEN
    RETURN 'lineage_conflict';
  END IF;
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION public.cancel_trial_balance_replacement(p_replacement_upload_id uuid, p_expected_version bigint)
RETURNS TABLE (outcome text, operation_id uuid, restored_upload_id uuid, file_path text, detail text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_rep public.trial_balance_uploads%ROWTYPE;
  v_prev public.trial_balance_uploads%ROWTYPE;
  v_prev_id uuid;
  v_auth record;
  v_restore text;
  v_op uuid;
  v_done public.trial_balance_upload_operations%ROWTYPE;
  v_block text;
  c_refused CONSTANT text := 'Refused replacement withdrawn; the trial balance it replaced was restored';
BEGIN
  SELECT t.replaces_upload_id INTO v_prev_id FROM public.trial_balance_uploads t WHERE t.id = p_replacement_upload_id;
  IF NOT FOUND THEN
    SELECT * INTO v_done FROM public.trial_balance_upload_operations o
     WHERE o.upload_id = p_replacement_upload_id AND o.kind = 'cancel_replacement' ORDER BY o.created_at DESC LIMIT 1;
    IF v_done.id IS NULL THEN
      RETURN QUERY SELECT 'not_a_replacement'::text, NULL::uuid, NULL::uuid, NULL::text, 'This trial balance no longer exists.'::text; RETURN;
    END IF;
    IF (SELECT basis FROM public.tbu_authorize(v_done.company_id)) IS NULL THEN
      RETURN QUERY SELECT 'forbidden'::text, NULL::uuid, NULL::uuid, NULL::text, 'You don''t have permission to manage this workspace''s source files.'::text; RETURN;
    END IF;
    RETURN QUERY SELECT 'already_cancelled'::text, v_done.id, v_done.related_upload_id, v_done.file_path, NULL::text; RETURN;
  END IF;

  PERFORM 1 FROM public.trial_balance_uploads t
   WHERE t.id IN (p_replacement_upload_id, v_prev_id) ORDER BY t.id FOR UPDATE;
  SELECT * INTO v_rep FROM public.trial_balance_uploads t WHERE t.id = p_replacement_upload_id;
  IF v_rep.id IS NULL THEN
    RETURN QUERY SELECT 'stale_version'::text, NULL::uuid, NULL::uuid, NULL::text, 'This trial balance changed. Refresh and try again.'::text; RETURN;
  END IF;

  SELECT * INTO v_auth FROM public.tbu_authorize(v_rep.company_id);
  IF v_auth.basis IS NULL THEN
    PERFORM public.tbu_log_event(v_rep.id, v_rep.company_id, v_rep.engagement_id, v_rep.period_year, v_rep.lifecycle_state, NULL,
      'user', auth.uid(), NULL, NULL, 'manage_source_files', 'denied', NULL, 'cancel replacement refused: no workspace authority');
    RETURN QUERY SELECT 'forbidden'::text, NULL::uuid, NULL::uuid, NULL::text, 'You don''t have permission to manage this workspace''s source files.'::text; RETURN;
  END IF;

  IF v_rep.replaces_upload_id IS NULL THEN
    RETURN QUERY SELECT 'not_a_replacement'::text, NULL::uuid, NULL::uuid, NULL::text, 'This trial balance did not replace another one.'::text; RETURN;
  END IF;
  SELECT * INTO v_prev FROM public.trial_balance_uploads t WHERE t.id = v_rep.replaces_upload_id;

  -- [20261109100000] A restore of this refused replacement already applied: the same answer again, nothing changed.
  IF v_rep.lifecycle_state = 'retired' AND v_rep.retired_reason = c_refused AND v_prev.id IS NOT NULL
     AND v_prev.superseded_by_upload_id IS NULL
     AND v_prev.lifecycle_state IN ('active_unprocessed', 'active_processing', 'active_processed', 'blocked') THEN
    RETURN QUERY SELECT 'already_restored'::text, NULL::uuid, v_prev.id, NULL::text, NULL::text; RETURN;
  END IF;

  IF v_prev.id IS NULL OR v_prev.lifecycle_state <> 'superseded' OR v_prev.superseded_by_upload_id IS DISTINCT FROM v_rep.id THEN
    RETURN QUERY SELECT 'lineage_conflict'::text, NULL::uuid, NULL::uuid, NULL::text,
      'The earlier trial balance is no longer linked to this replacement, so it cannot be restored automatically.'::text; RETURN;
  END IF;

  -- Evidence outranks the version check (processing start bumps version).
  IF v_rep.lifecycle_state <> 'active_unprocessed' OR public.tbu_upload_evidence(v_rep.id, v_prev.id) IS NOT NULL THEN
    -- [20261109100000] A processed replacement is restorable only when its check REFUSED it (see the header).
    v_block := public.tbu_refused_replacement_block(v_rep.id);
    IF v_block = 'not_refused' THEN
      RETURN QUERY SELECT 'replacement_processed'::text, NULL::uuid, NULL::uuid, NULL::text,
        'The replacement has already been processed, so it cannot be cancelled. Replace it with another upload instead.'::text; RETURN;
    END IF;
    IF v_block IS NOT NULL THEN
      RETURN QUERY SELECT 'not_restorable'::text, NULL::uuid, NULL::uuid, NULL::text,
        CASE v_block
          WHEN 'processing_in_progress' THEN 'This file is being checked right now. Wait for the check to finish, then try again.'
          WHEN 'not_current' THEN 'A newer trial balance is now current for this period, so the earlier one cannot be restored over it.'
          WHEN 'certified' THEN 'This file has a checked result, so the earlier trial balance cannot be restored over it.'
          WHEN 'dependent_evidence' THEN 'Work has been recorded against this file, so the earlier trial balance cannot be restored over it.'
          ELSE 'The earlier trial balance is no longer linked to this replacement, so it cannot be restored automatically.'
        END::text; RETURN;
    END IF;
    IF p_expected_version IS NULL OR v_rep.version <> p_expected_version THEN
      RETURN QUERY SELECT 'stale_version'::text, NULL::uuid, NULL::uuid, NULL::text, 'This trial balance changed since you last viewed it. Refresh and try again.'::text; RETURN;
    END IF;

    v_restore := public.tbu_derived_active_state(v_prev);
    PERFORM set_config('axiom.tbu_lifecycle_op', 'cancel_replacement', true);
    -- Free the period's active slot first (the refused upload is retired, not deleted), then reactivate the predecessor.
    UPDATE public.trial_balance_uploads t
       SET lifecycle_state = 'retired', retired_at = now(), retired_by = auth.uid(), retired_by_membership_id = v_auth.membership_id,
           retired_reason = c_refused, version = t.version + 1
     WHERE t.id = v_rep.id;
    UPDATE public.trial_balance_uploads t
       SET superseded_by_upload_id = NULL, lifecycle_state = v_restore, retired_at = NULL, retired_by = NULL,
           retired_by_membership_id = NULL, retired_reason = NULL, version = t.version + 1
     WHERE t.id = v_prev.id;
    PERFORM public.tbu_log_event(v_rep.id, v_rep.company_id, v_rep.engagement_id, v_rep.period_year, v_rep.lifecycle_state, 'retired',
      'user', auth.uid(), v_auth.membership_id, v_auth.basis, v_auth.capability, 'applied', NULL, c_refused);
    PERFORM public.tbu_log_event(v_prev.id, v_prev.company_id, v_prev.engagement_id, v_prev.period_year, 'superseded', v_restore,
      'user', auth.uid(), v_auth.membership_id, v_auth.basis, v_auth.capability, 'applied', NULL, 'Restored: refused replacement ' || v_rep.id::text || ' withdrawn');
    PERFORM set_config('axiom.tbu_lifecycle_op', '', true);
    RETURN QUERY SELECT 'restored'::text, NULL::uuid, v_prev.id, NULL::text, NULL::text; RETURN;
  END IF;

  IF p_expected_version IS NULL OR v_rep.version <> p_expected_version THEN
    RETURN QUERY SELECT 'stale_version'::text, NULL::uuid, NULL::uuid, NULL::text, 'This trial balance changed since you last viewed it. Refresh and try again.'::text; RETURN;
  END IF;

  v_restore := public.tbu_derived_active_state(v_prev);

  PERFORM set_config('axiom.tbu_lifecycle_op', 'cancel_replacement', true);
  INSERT INTO public.trial_balance_upload_operations
    (kind, state, upload_id, related_upload_id, company_id, period_year, actor_user_id, actor_membership_id,
     authority_basis, authority_capability, file_path, row_snapshot)
  VALUES ('cancel_replacement', 'storage_cleanup_pending', v_rep.id, v_prev.id, v_rep.company_id, v_rep.period_year,
          auth.uid(), v_auth.membership_id, v_auth.basis, v_auth.capability, public.tbu_bound_storage_path(v_rep), to_jsonb(v_rep))
  RETURNING id INTO v_op;
  -- Free the period's active slot first, then reactivate the predecessor. The deferred FK from
  -- v_prev.superseded_by_upload_id is satisfied at COMMIT because the link is cleared below.
  DELETE FROM public.trial_balance_uploads t WHERE t.id = v_rep.id;
  UPDATE public.trial_balance_uploads t
     SET superseded_by_upload_id = NULL, lifecycle_state = v_restore, retired_at = NULL, retired_by = NULL,
         retired_by_membership_id = NULL, retired_reason = NULL, version = t.version + 1
   WHERE t.id = v_prev.id;
  PERFORM public.tbu_log_event(v_rep.id, v_rep.company_id, v_rep.engagement_id, v_rep.period_year, v_rep.lifecycle_state, 'discarded',
    'user', auth.uid(), v_auth.membership_id, v_auth.basis, v_auth.capability, 'applied', v_op, 'Replacement cancelled');
  PERFORM public.tbu_log_event(v_prev.id, v_prev.company_id, v_prev.engagement_id, v_prev.period_year, 'superseded', v_restore,
    'user', auth.uid(), v_auth.membership_id, v_auth.basis, v_auth.capability, 'applied', v_op, 'Restored: replacement ' || v_rep.id::text || ' cancelled');
  PERFORM set_config('axiom.tbu_lifecycle_op', '', true);

  RETURN QUERY SELECT 'cancelled'::text, v_op, v_prev.id, (SELECT o.file_path FROM public.trial_balance_upload_operations o WHERE o.id = v_op), NULL::text;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_trial_balance_removal_eligibility(p_upload_id UUID)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_row   public.trial_balance_uploads%ROWTYPE;
  v_bound TEXT;
BEGIN
  SELECT * INTO v_row FROM public.trial_balance_uploads t WHERE t.id = p_upload_id;
  -- A missing upload and one the caller may not manage answer identically.
  IF v_row.id IS NULL OR v_row.company_id IS NULL OR (SELECT a.basis FROM public.tbu_authorize(v_row.company_id) a) IS NULL THEN
    RETURN jsonb_build_object('outcome', 'forbidden');
  END IF;
  IF v_row.lifecycle_state NOT IN ('active_unprocessed', 'active_processing', 'active_processed', 'blocked') THEN
    RETURN jsonb_build_object('outcome', 'not_active', 'version', v_row.version);
  END IF;
  IF v_row.lifecycle_state = 'active_unprocessed' AND public.tbu_upload_evidence(v_row.id, v_row.replaces_upload_id) IS NULL THEN
    RETURN jsonb_build_object('outcome', CASE WHEN v_row.replaces_upload_id IS NOT NULL THEN 'cancel_replacement' ELSE 'discard' END,
                              'version', v_row.version);
  END IF;
  -- [20261109100000] A refused replacement: the trial balance it replaced can be restored (exactly when the server would).
  IF v_row.replaces_upload_id IS NOT NULL AND public.tbu_refused_replacement_block(v_row.id) IS NULL THEN
    RETURN jsonb_build_object('outcome', 'restore_previous', 'version', v_row.version, 'restores_upload_id', v_row.replaces_upload_id);
  END IF;
  v_bound := public.tbu_issued_output_binding(v_row.company_id, v_row.period_year);
  IF v_bound IS NOT NULL THEN
    RETURN jsonb_build_object('outcome', 'issued_output_bound', 'binding', v_bound, 'version', v_row.version);
  END IF;
  RETURN jsonb_build_object('outcome', 'remove', 'version', v_row.version);
END;
$$;

